@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#f2f1e7;--muted:#aeb8a9;--lime:#c8df7b;--panel:rgba(17,26,22,.84);--line:rgba(230,239,214,.14);font-family:Manrope,system-ui,sans-serif;color:var(--ink)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#18251d}body{user-select:none;-webkit-user-select:none}#game{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#283b2e}#world{position:absolute;inset:0;width:100%;height:100%;display:block;cursor:crosshair;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 45%,transparent 35%,rgba(5,12,9,.14) 78%,rgba(5,11,8,.52) 150%);box-shadow:inset 0 0 90px rgba(5,13,9,.28)}.topbar{position:absolute;top:0;left:0;right:0;height:82px;padding:0 40px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,16,12,.76),rgba(8,16,12,0));pointer-events:none}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:34px;height:34px;border:1px solid rgba(200,223,123,.72);color:var(--lime);font:800 21px 'Barlow Condensed',sans-serif;display:grid;place-items:center;transform:rotate(-8deg)}.brand b{font:800 16px 'Barlow Condensed',sans-serif;letter-spacing:3px}.brand small{display:block;color:#a8b2a1;font:9px 'DM Mono',monospace;letter-spacing:1.55px;margin-top:3px}.mission{display:flex;align-items:center;gap:11px;font:10px 'DM Mono',monospace;letter-spacing:1.25px;color:#e3e7d9}.mission i{font-style:normal;color:var(--lime)}.mission span:last-child{color:var(--lime)}.live-dot,.status-pip{width:7px;height:7px;border-radius:50%;background:#c9e282;box-shadow:0 0 11px #c9e282;display:inline-block}.icon-button{pointer-events:auto;background:rgba(15,24,19,.52);border:1px solid var(--line);color:#e8eddf;width:37px;height:37px;font-size:17px;border-radius:2px;cursor:pointer}.left-hud{position:absolute;left:40px;top:108px;width:210px;display:grid;gap:10px}.status-card,.objective-card,.map-frame,.weapon-card{background:linear-gradient(140deg,rgba(15,24,19,.87),rgba(19,31,24,.66));border:1px solid rgba(231,239,218,.12);backdrop-filter:blur(8px);box-shadow:0 8px 24px rgba(5,10,7,.13)}.status-card{padding:14px 15px 13px}.card-label{display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;letter-spacing:1.35px;color:#bec8b7}.card-label span:last-child{color:#f3f4e9}.meter{height:4px;background:rgba(232,239,219,.13);margin-top:8px}.meter-fill{height:100%;transition:width .25s}.health-fill{background:linear-gradient(90deg,#d9e987,#91bd68);box-shadow:0 0 8px rgba(203,226,125,.22)}.lower{margin-top:13px}.thin{height:2px;margin-top:7px}.armor-fill{background:#80b3b0}.objective-card{padding:13px 15px 14px;border-left:2px solid rgba(199,224,121,.7)}.eyebrow{display:block;color:var(--lime);font:9px 'DM Mono',monospace;letter-spacing:1.4px;margin-bottom:7px}.objective-card b{font:600 12px Manrope,sans-serif;display:block}.objective-card small{display:block;color:#aeb8a7;font:9px 'DM Mono',monospace;margin-top:6px;letter-spacing:.25px}.right-hud{position:absolute;right:40px;top:108px;width:190px;display:grid;gap:10px}.map-frame{padding:12px 12px 10px}.map-heading{display:flex;justify-content:space-between;align-items:center;font:9px 'DM Mono',monospace;letter-spacing:1.05px;color:#dce4d4}.map-coords{font-size:8px;color:#9eac9d}.map-frame canvas{display:block;width:100%;aspect-ratio:1;margin-top:10px;border:1px solid rgba(223,235,209,.16);background:#253b2d}.map-legend{display:flex;gap:15px;margin-top:9px;font:8px 'DM Mono',monospace;color:#b8c2b5}.map-legend span{display:flex;align-items:center;gap:5px}.legend-player,.legend-hostile{display:inline-block;width:6px;height:6px;border-radius:50%;background:#d6ed91}.legend-hostile{background:#ff785e}.weapon-card{padding:13px 14px 11px;display:grid;grid-template-columns:1fr auto;align-items:center}.weapon-name span{font:700 13px 'Barlow Condensed',sans-serif;letter-spacing:1.4px}.weapon-name small{display:block;color:#9eaa9b;font:7px 'DM Mono',monospace;letter-spacing:.7px;margin-top:2px}.ammo{display:flex;align-items:baseline;gap:4px}.ammo strong{font:700 25px 'Barlow Condensed',sans-serif;color:#f5f4e7}.ammo span{font:11px 'DM Mono',monospace;color:#aab5a4}.ammo span b{font-weight:400}.ammo-label{grid-column:1/3;border-top:1px solid rgba(230,239,214,.12);padding-top:8px;margin-top:10px;color:#9ba99a;font:8px 'DM Mono',monospace;letter-spacing:.8px;display:flex;justify-content:space-between}.ammo-label span{color:#e1bc79}.bottom-hud{position:absolute;bottom:0;left:0;right:0;min-height:59px;padding:0 40px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(0deg,rgba(7,14,10,.8),rgba(7,14,10,.48) 65%,transparent);pointer-events:none}.hint{display:flex;align-items:center;gap:6px;color:#aeb9a8;font:8px 'DM Mono',monospace;letter-spacing:.6px}.hint kbd{padding:4px 5px;min-width:19px;text-align:center;border:1px solid rgba(230,239,214,.23);border-radius:2px;color:#e4ebdc;font:8px 'DM Mono',monospace;background:rgba(236,241,222,.07)}.hint span{margin-left:2px}.hint i,.controls-note i{height:13px;border-left:1px solid rgba(230,239,214,.25);margin:0 7px;font-style:normal}.center-status{display:flex;align-items:center;gap:8px;font:8px 'DM Mono',monospace;color:#c5cfbf;letter-spacing:1px}.status-pip{width:5px;height:5px}.toast{position:absolute;left:50%;top:102px;transform:translate(-50%,-12px);padding:9px 16px;background:rgba(15,25,20,.9);border:1px solid rgba(205,228,129,.45);color:#e8eddf;font:9px 'DM Mono',monospace;letter-spacing:1px;opacity:0;transition:.22s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,rgba(9,18,13,.83),rgba(9,18,13,.52) 54%,rgba(9,18,13,.07)),linear-gradient(0deg,rgba(9,18,13,.55),transparent 40%);transition:opacity .45s,visibility .45s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-card{width:min(600px,calc(100% - 48px));margin-left:-17%;padding-top:25px}.overline{display:flex;align-items:center;gap:9px;font:9px 'DM Mono',monospace;letter-spacing:1.7px;color:#d6ddce}.overline .live-dot{width:6px;height:6px}.overlay h1{font:800 clamp(54px,7vw,91px)/.79 'Barlow Condensed',Impact,sans-serif;letter-spacing:-1px;margin:27px 0 20px;color:#f0f0e5;text-shadow:0 3px 25px rgba(0,0,0,.2)}.overlay h1 em{font-style:normal;color:#d4e789}.overlay p{max-width:455px;color:#d2d9cb;font-size:13px;line-height:1.8;margin:0 0 24px}.feature-row{display:flex;gap:18px;flex-wrap:wrap;font:8px 'DM Mono',monospace;letter-spacing:.55px;color:#bdc9b8}.feature-row span::first-letter{color:var(--lime)}.start-button{margin-top:29px;height:48px;min-width:228px;padding:0 19px;border:0;background:#d3e788;color:#192419;font:800 11px 'DM Mono',monospace;letter-spacing:.8px;cursor:pointer;box-shadow:0 6px 25px rgba(191,224,113,.12);transition:transform .2s,background .2s}.start-button:hover{background:#e2f2a5;transform:translateY(-2px)}.start-button span{font-size:17px;padding-left:13px}.controls-note{display:flex;align-items:center;gap:11px;margin-top:24px;color:#aeb9a7;font:8px 'DM Mono',monospace;letter-spacing:.45px}.controls-note b{font-weight:500;color:#e2e8d9}.controls-note i{height:10px;margin:0}.overlay-meta{position:absolute;bottom:26px;left:40px;right:40px;display:flex;justify-content:space-between;color:rgba(226,234,216,.7);font:8px 'DM Mono',monospace;letter-spacing:1px}.overlay-meta i{font-style:normal;color:var(--lime);padding:0 5px}.crosshair{position:absolute;left:50%;top:50%;width:18px;height:18px;pointer-events:none;transform:translate(-50%,-50%);opacity:0;transition:opacity .2s}.crosshair.visible{opacity:.82}.crosshair i{position:absolute;background:#f3f1dc;box-shadow:0 0 3px #162018}.crosshair i:nth-child(1){width:1px;height:5px;left:8px;top:0}.crosshair i:nth-child(2){width:1px;height:5px;left:8px;bottom:0}.crosshair i:nth-child(3){width:5px;height:1px;left:0;top:8px}.crosshair i:nth-child(4){width:5px;height:1px;right:0;top:8px}.crosshair b{position:absolute;left:7px;top:7px;width:3px;height:3px;border:1px solid #e8ebd9;border-radius:50%}.mobile-controls{display:none}.overlay.paused{background:rgba(8,16,12,.57);backdrop-filter:blur(4px)}
@media(max-width:850px){.topbar{padding:0 20px;height:66px}.left-hud{left:18px;top:80px;width:190px}.right-hud{right:18px;top:80px;width:165px}.overlay-card{margin-left:0}.bottom-hud{padding:0 20px}.overlay-meta{left:20px;right:20px}.overlay p{font-size:12px;max-width:420px}.mission{font-size:9px}.map-frame{padding:9px}.map-frame canvas{margin-top:7px}.status-card{padding:11px 12px}.objective-card{padding:11px 12px}}
@media(max-width:600px){.topbar{height:58px;padding:0 14px}.brand-mark{width:29px;height:29px;font-size:18px}.brand{gap:8px}.brand b{font-size:13px;letter-spacing:2px}.brand small{font-size:7px}.mission{font-size:8px;gap:6px;letter-spacing:.6px}.icon-button{width:32px;height:32px}.left-hud{left:12px;top:68px;width:143px;gap:7px}.right-hud{right:12px;top:68px;width:125px;gap:7px}.status-card{padding:9px}.card-label{font-size:8px}.lower{margin-top:9px}.objective-card{padding:9px}.objective-card b{font-size:10px}.objective-card small{font-size:7px;line-height:1.45}.eyebrow{font-size:7px;margin-bottom:5px}.map-frame{padding:7px}.map-heading{font-size:7px}.map-coords{font-size:6px}.map-legend{gap:8px;font-size:6px;margin-top:6px}.weapon-card{padding:9px}.weapon-name span{font-size:11px}.weapon-name small{font-size:6px}.ammo strong{font-size:20px}.ammo-label{font-size:6px;padding-top:6px;margin-top:7px}.bottom-hud{padding:0 12px;min-height:47px}.hint{font-size:7px;gap:4px}.hint kbd{font-size:7px;padding:3px;min-width:16px}.hint i{margin:0 3px;height:9px}.center-status{font-size:7px;gap:5px}.right-hint{display:none}.overlay{align-items:flex-start;background:linear-gradient(90deg,rgba(9,18,13,.79),rgba(9,18,13,.45)),linear-gradient(0deg,rgba(9,18,13,.48),transparent 50%)}.overlay-card{width:calc(100% - 44px);margin-top:20vh}.overlay h1{font-size:64px;margin:20px 0 15px}.overlay p{font-size:11px;line-height:1.65;max-width:380px}.feature-row{gap:10px;font-size:7px}.start-button{margin-top:21px;height:44px}.controls-note{font-size:7px;gap:6px;flex-wrap:wrap}.overlay-meta{bottom:12px;font-size:6px;letter-spacing:.4px}.overlay-meta span:first-child{max-width:50%}.mobile-controls{position:absolute;inset:auto 0 42px;display:flex;justify-content:space-between;align-items:flex-end;padding:0 22px;pointer-events:none}.joystick{position:relative;width:112px;height:112px;pointer-events:auto;touch-action:none;display:flex;align-items:center;justify-content:center}.joy-ring{position:absolute;inset:7px;border:1px solid rgba(235,242,219,.4);border-radius:50%;background:rgba(16,25,19,.23);box-shadow:inset 0 0 20px rgba(5,10,7,.2)}.joy-knob{position:absolute;width:43px;height:43px;left:35px;top:35px;border-radius:50%;background:rgba(204,225,129,.62);border:1px solid rgba(241,246,219,.55);box-shadow:0 2px 10px rgba(0,0,0,.3)}.joystick span{position:absolute;bottom:-2px;color:rgba(237,242,225,.7);font:7px 'DM Mono',monospace;letter-spacing:1px}.fire-button{pointer-events:auto;touch-action:none;width:67px;height:67px;border:1px solid rgba(228,237,207,.65);border-radius:50%;background:rgba(43,58,43,.63);color:#f1f3e5;box-shadow:0 3px 16px rgba(0,0,0,.23);font:700 8px 'DM Mono',monospace;letter-spacing:1px}.fire-button i{display:block;font-style:normal;font-size:17px;line-height:15px;color:#d5e889}.fire-button:active{background:rgba(199,224,121,.68)}.crosshair{display:none}}
@media(max-height:650px) and (max-width:600px){.overlay-card{margin-top:12vh}.overlay h1{font-size:52px;margin:13px 0}.overlay p{margin-bottom:13px}.feature-row{display:none}.start-button{margin-top:13px}.controls-note{margin-top:13px}.mobile-controls{bottom:40px}.joystick{width:95px;height:95px}.joy-knob{left:29px;top:29px}}

(() => {
  'use strict';
  const canvas = document.querySelector('#world');
  const ctx = canvas.getContext('2d', { alpha: false });
  const mini = document.querySelector('#minimap');
  const mctx = mini.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const WORLD = 3600, TILE = 128, TAU = Math.PI * 2;
  const biomeNames = ['PINEWOOD', 'GOLDEN MEADOW', 'AUTUMN FOREST', 'HIGHLANDS'];
  const palettes = [
    { ground: '#405b43', alt: '#496449', dark: '#344e3a', leaf: ['#294936','#31563c','#3c6544','#466a49'], flower:'#d0d68e' },
    { ground: '#829052', alt: '#8d9855', dark: '#737e45', leaf: ['#53734a','#65844d','#779252','#8b9b5b'], flower:'#e9d293' },
    { ground: '#68784a', alt: '#75834e', dark: '#586640', leaf: ['#76533a','#966244','#b07143','#a47742'], flower:'#d5b97a' },
    { ground: '#65705b', alt: '#737b62', dark: '#545e50', leaf: ['#4c6252','#5a715b','#71805c','#89875b'], flower:'#d7d4a0' }
  ];
  let W = 0, H = 0, dpr = 1, last = 0, gameState = 'menu', elapsed = 0, toastTimer = 0;
  let seed = 93751;
  const rand = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
  const hash = (x, y, n=0) => { let a = Math.sin(x * 127.1 + y * 311.7 + n * 74.7) * 43758.5453; return a - Math.floor(a); };
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const lerp = (a,b,t) => a+(b-a)*t;
  const dist2 = (a,b) => (a.x-b.x)**2 + (a.y-b.y)**2;
  const player = { x: 1800, y: 1800, vx: 0, vy: 0, angle: -0.5, health: 100, armor: 65, ammo: 30, reserve: 120, kills: 0, shoot: 0, reload: 0, invuln: 0, moving: 0 };
  const camera = { x: 0, y: 0 };
  const keys = new Set(), flora = [], animals = [], enemies = [], bullets = [], particles = [], props = [], pickups = [];
  let pointer = { x: 0, y: 0, down: false }, joy = { x: 0, y: 0, active: false }, fireHeld = false;

  function biomeAt(x,y) {
    // Four generous ecoregions meet in a naturally varied central transition.
    const nx = x / WORLD, ny = y / WORLD;
    if (nx < .5 && ny < .5) return 0;
    if (nx >= .5 && ny < .5) return 2;
    if (nx < .5 && ny >= .5) return 1;
    return 3;
  }
  function biomeNameAt(x,y) { return biomeNames[biomeAt(x,y)]; }
  function buildWorld() {
    seed = 897239;
    for (let i=0;i<1370;i++) {
      const x=rand()*WORLD,y=rand()*WORLD,b=biomeAt(x,y),r=rand();
      if (r<.61) flora.push({x,y,type:'tree',size: .7+rand()*.78, variant:Math.floor(rand()*4), b, phase:rand()*TAU});
      else if (r<.76) flora.push({x,y,type:'pine',size:.65+rand()*.8,variant:Math.floor(rand()*3),b,phase:rand()*TAU});
      else if(r<.88) flora.push({x,y,type:'rock',size:.45+rand()*.8,b,variant:Math.floor(rand()*3)});
      else flora.push({x,y,type:'plant',size:.55+rand()*1.25,b,variant:Math.floor(rand()*4),phase:rand()*TAU});
    }
    for(let i=0;i<29;i++) {
      let x=220+rand()*(WORLD-440), y=220+rand()*(WORLD-440);
      props.push({x,y,type:i<17?'crate':'barrel',size:i<17?18:13,vx:0,vy:0,angle:rand()*TAU,health:1});
    }
    // Calm wildlife; animals are never targets and scatter from combat.
    for(let i=0;i<34;i++) {
      const x=100+rand()*(WORLD-200),y=100+rand()*(WORLD-200);
      animals.push({x,y,vx:0,vy:0,angle:rand()*TAU,kind:rand()<.72?'deer':'fox',size:rand()<.72?1:.76,turn:rand()*4,alert:0});
    }
    for(let i=0;i<8;i++) spawnEnemy(520+rand()*220,Math.PI*2*rand());
  }
  function spawnEnemy(radius=500, angle=Math.random()*TAU) {
    const x=clamp(player.x+Math.cos(angle)*radius,80,WORLD-80), y=clamp(player.y+Math.sin(angle)*radius,80,WORLD-80);
    enemies.push({x,y,vx:0,vy:0,angle:angle+Math.PI,health:3,maxHealth:3,fire:1+Math.random()*1.5,stun:0,phase:Math.random()*TAU,dead:false});
  }
  function resize() {
    const rect=canvas.getBoundingClientRect(); W=rect.width;H=rect.height;dpr=Math.min(window.devicePixelRatio||1,2.5);
    canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  window.addEventListener('resize',resize); resize(); buildWorld();

  function riverPath(index=0) {
    if(index===0){ctx.moveTo(-100,590);ctx.bezierCurveTo(780,480,750,1110,1580,1180);ctx.bezierCurveTo(2200,1240,2120,1890,2750,2010);ctx.bezierCurveTo(3210,2090,3260,2600,3700,2800);}
    else {ctx.moveTo(500,-100);ctx.bezierCurveTo(650,380,1250,350,1370,780);ctx.bezierCurveTo(1500,1050,1240,1300,1450,1510);}
  }
  function drawTerrain() {
    const left=Math.max(0,Math.floor(camera.x/TILE)-1), top=Math.max(0,Math.floor(camera.y/TILE)-1);
    const right=Math.min(Math.ceil(WORLD/TILE),Math.ceil((camera.x+W)/TILE)+1), bottom=Math.min(Math.ceil(WORLD/TILE),Math.ceil((camera.y+H)/TILE)+1);
    for(let gy=top;gy<bottom;gy++) for(let gx=left;gx<right;gx++) {
      const x=gx*TILE,y=gy*TILE,b=biomeAt(x+TILE/2,y+TILE/2),p=palettes[b],n=hash(gx,gy);
      ctx.fillStyle=n>.54?p.alt:(n<.13?p.dark:p.ground);ctx.fillRect(x,y,TILE+1,TILE+1);
      // Broad, fine-grained ground cover, kept deterministic so it never shimmers.
      for(let j=0;j<10;j++) {
        const px=x+hash(gx,gy,j+4)*TILE,py=y+hash(gx,gy,j+21)*TILE;
        ctx.globalAlpha=.07+hash(gx,gy,j+38)*.11;ctx.fillStyle=j%3?'#d8d09a':'#182b20';
        if(j%3===0){ctx.beginPath();ctx.ellipse(px,py,4+hash(gx,gy,j+51)*7,1.3,hash(gx,gy,j+67),0,TAU);ctx.fill();}
        else {ctx.beginPath();ctx.arc(px,py,1+hash(gx,gy,j+61)*2,0,TAU);ctx.fill();}
      }
      ctx.globalAlpha=1;
    }
    ctx.save();ctx.lineCap='round';ctx.lineJoin='round';
    for(let r=0;r<2;r++){
      ctx.beginPath();riverPath(r);ctx.strokeStyle='rgba(25,42,37,.32)';ctx.lineWidth=r===0?215:104;ctx.stroke();
      ctx.beginPath();riverPath(r);ctx.strokeStyle='#6b927d';ctx.lineWidth=r===0?193:87;ctx.stroke();
      ctx.beginPath();riverPath(r);ctx.strokeStyle='#739f96';ctx.lineWidth=r===0?159:67;ctx.stroke();
      ctx.beginPath();riverPath(r);ctx.setLineDash([35,40]);ctx.lineDashOffset=-elapsed*25;ctx.strokeStyle='rgba(186,221,202,.29)';ctx.lineWidth=2;ctx.stroke();ctx.setLineDash([]);
    }
    // The falls where the feeder stream spills into the main river.
    const fx=1420,fy=1045, pulse=.5+.5*Math.sin(elapsed*3.1);
    const grad=ctx.createRadialGradient(fx,fy,10,fx,fy,78);grad.addColorStop(0,'rgba(226,241,211,.5)');grad.addColorStop(.35,'rgba(176,216,197,.38)');grad.addColorStop(1,'rgba(177,218,200,0)');
    ctx.fillStyle=grad;ctx.beginPath();ctx.ellipse(fx,fy,86,63, -.38,0,TAU);ctx.fill();
    ctx.strokeStyle=`rgba(237,245,219,${.42+pulse*.2})`;ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(fx-31,fy-12);ctx.quadraticCurveTo(fx,fy+8,fx+36,fy+17);ctx.stroke();
    for(let i=0;i<14;i++){const a=i*2.4+elapsed*1.1;ctx.fillStyle=`rgba(225,242,219,${.18+hash(i,1)*.25})`;ctx.beginPath();ctx.arc(fx+Math.cos(a)*(30+(i%4)*8),fy+Math.sin(a)*20,1.5+(i%3),0,TAU);ctx.fill();}
    ctx.restore();
  }
  function drawTree(o) {
    const p=palettes[o.b],s=o.size,x=o.x,y=o.y;
    ctx.save();ctx.translate(x,y);ctx.scale(s,s);
    ctx.fillStyle='rgba(18,30,19,.25)';ctx.beginPath();ctx.ellipse(6,13,22,10,0,0,TAU);ctx.fill();
    ctx.fillStyle=o.b===0?'#523d2d':o.b===2?'#59402e':'#594b34';ctx.fillRect(-3,-8,7,18);
    for(let k=3;k>=0;k--){const a=o.variant===0?0:((k%2)*2-1)*(o.variant===1?7:4);ctx.fillStyle=p.leaf[(o.variant+k)%p.leaf.length];ctx.beginPath();ctx.ellipse(a+(k%2?4:-3),-k*5-3,13-k*1.2,10-k*.6,((o.variant+k)%3)*.17,0,TAU);ctx.fill();}
    ctx.globalAlpha=.34;ctx.fillStyle='#d5df9a';ctx.beginPath();ctx.ellipse(-5,-16,7,4,-.5,0,TAU);ctx.fill();ctx.restore();
  }
  function drawPine(o) {
