const mixColor = (a,b,t) => {
  const ca=parseInt(a.slice(1),16),cb=parseInt(b.slice(1),16),r=Math.round(lerp(ca>>16,cb>>16,t)),g=Math.round(lerp((ca>>8)&255,(cb>>8)&255,t)),bl=Math.round(lerp(ca&255,cb&255,t));
  return `rgb(${r},${g},${bl})`;
};
