216:       const t=i/80;
217:       const px=lerp(-100,3700,t),py=590+Math.sin(t*5.7)*355+Math.sin(t*11.3)*72;
218:       const dx=x-px,dy=y-py,d=dx*dx+dy*dy;if(d<best)best=d;
